export const SUPPORTED_LANGUAGES = ["en", "th"] as const;
export type Language = (typeof SUPPORTED_LANGUAGES)[number];

const LANGUAGE_NATIVE_LABELS: Record<Language, string> = {
  en: "English",
  th: "à¹„à¸—à¸¢",
};

const LANGUAGE_LOCALES: Record<Language, string> = {
  en: "en-US",
  th: "th-TH",
};

export const getLanguageNativeLabel = (language: Language): string =>
  LANGUAGE_NATIVE_LABELS[language] ?? LANGUAGE_NATIVE_LABELS.en;

export const getLanguageLocale = (language: Language): string =>
  LANGUAGE_LOCALES[language] ?? LANGUAGE_LOCALES.en;

